	/* @Override */
	public void setHighlight(ProgramSelection newHighlight) {
		currentHighlight = newHighlight;
		if (newHighlight == null) {
			return;
		}

		if (!tool.isVisible(this)) {
			return;
		}

		ByteBlockSelection highlight = blockSet.getBlockSelection(currentHighlight);
		panel.setViewerHighlight(highlight);
		contextChanged();
		plugin.highlightChanged(this, newHighlight);

	}

	void enablePaste(bool enabled) {
		clipboardProvider.setPasteEnabled(enabled);
	}

	protected void doSetProgram(Program newProgram) {
		if (program != null) {
			program.removeListener(this);
		}

		program = newProgram;
		clipboardProvider.setProgram(newProgram);

		if (newProgram != null) {
			newProgram.addListener(this);
		}
		foreach (ByteViewerComponent byteViewerComponent in viewMap.values()) {
			DataFormatModel dataModel = byteViewerComponent.getDataModel();
			if (dataModel is ProgramDataFormatModel pdfm) {
				pdfm.setProgram(newProgram);
			}
		}

		setByteBlocks(null);
		updateTitle();
		contextChanged();
	}

	protected void updateTitle() {
		string title =
			"Bytes: " + (program == null ? "No Program" : program.getDomainFile().getName());
		if (!isConnected()) {
			title = "[" + title + "]";
		}
		setTitle(title);
		updateSubTitle();
	}

	private void updateSubTitle() {
		// Note: the Listing has similar code
		ProgramSelection selection = liveSelection != null ? liveSelection : currentSelection;
		string selectionInfo = null;
		if (selection != null && !selection.isEmpty()) {
			long n = selection.getNumAddresses();
			string nString = Long.toString(n);
			if (n == 1) {
				selectionInfo = "(1 byte selected)";
			}
			else {
				selectionInfo = '(' + nString + " bytes selected)";
			}
		}

		setSubTitle(selectionInfo);
	}

